  var z = txt(c, "200", F_NUM, 210, INK, [530, 1158]); slam(z, k.zahl - f2s(2)); yellowPop(z, k.zahl + f2s(1));
  var j = txt(c, "Jahre", F_SERIF_I, 66, INK, [830, 1126]); j.inPoint = k.jahre - f2s(2);
  focusHunt(c, 0, true);
